1	// SPDX-License-Identifier: Apache-2.0
2	
3	//! Bearer-enforcement middleware for the protected `/v1` HTTP surface (spec §7.4, D14).
4	//! Extracts `Authorization: Bearer <token>` — the ONLY accepted credential source (no
5	//! cookies, no query parameters) — runs it through `AuthnSvc::resolve(.., Enabled)` (which
6	//! JIT-provisions an unknown identity, AC 2), and, on success, inserts an [`AuthContext`]
7	//! request extension for downstream handlers. Every rejection short-circuits through the
8	//! shared `AuthnApiError` funnel (D12): a missing or malformed header, like any other
9	//! `InvalidToken`, is a 401 `invalid_token` with a `WWW-Authenticate` challenge; the token
10	//! itself is never logged (nothing here logs it, and `AuthnError`'s own contract keeps
11	//! claim/token material out of its `Display`).
12	
13	use axum::extract::{Request, State};
14	use axum::http::header;
15	use axum::middleware::Next;
16	use axum::response::{IntoResponse, Response};
17	use paigasus_iam_core::{AuthnError, Issuer, PrincipalId, TokenDefect};
18	
19	use super::AppState;
20	use super::authn::AuthnApiError;
21	use crate::application::authenticate_token::Provisioning;
22	
23	/// The authenticated request context the middleware attaches on success (D13: the hot path
24	/// resolves the principal only — no membership fetch; that stays in `Introspect`). M2
25	/// handlers don't read it yet; M3 (authorization) and M5 (audit) will, and Task 12 reuses
26	/// this exact shape for the gRPC surface — so the field set is deliberately fixed here.
27	#[derive(Clone)]
28	pub struct AuthContext {
29	    pub principal_id: PrincipalId,
30	    pub issuer: Issuer,
31	    pub subject: String,
32	}
33	
34	/// Enforces a valid bearer token on the request before it reaches a protected handler
35	/// (D14 — wired via `route_layer` inside `router()`, so the `oneshot` test harness
36	/// exercises it too). Applied only to the tenancy sub-router; `/healthz`, `/readyz`, and
37	/// `POST /v1/authn/introspect` stay outside it (spec §7.4).
38	pub async fn require_bearer(State(state): State<AppState>, mut request: Request, next: Next) -> Response {
39	    let Some(token) = bearer_token(&request) else {
40	        // A missing or malformed `Authorization` header is indistinguishable, to a caller,
41	        // from a rejected token: both are 401 `invalid_token` + `WWW-Authenticate` (D12).
42	        return AuthnApiError(AuthnError::InvalidToken(TokenDefect::Malformed)).into_response();
43	    };
44	
45	    match state.authn.resolve(&token, Provisioning::Enabled).await {
46	        Ok(principal) => {
47	            request.extensions_mut().insert(AuthContext {
48	                principal_id: principal.principal_id,
49	                issuer: principal.issuer,
50	                subject: principal.subject,
51	            });
52	            next.run(request).await
53	        }
54	        Err(err) => AuthnApiError(err).into_response(),
55	    }
56	}
57	
58	/// Extracts the bearer token from the `Authorization` header — the sole accepted source.
59	/// Returns `None` for an absent header, a non-UTF-8 value, a non-`Bearer` scheme, or an
60	/// empty credential. The scheme match is ASCII-case-insensitive per RFC 7235 §2.1.
61	fn bearer_token(request: &Request) -> Option<String> {
62	    let value = request.headers().get(header::AUTHORIZATION)?.to_str().ok()?;
63	    let (scheme, token) = value.split_once(' ')?;
64	    if !scheme.eq_ignore_ascii_case("Bearer") {
65	        return None;
66	    }
67	    let token = token.trim();
68	    if token.is_empty() {
69	        return None;
70	    }
71	    Some(token.to_string())
72	}
73

