3	//! The gRPC authn surface (spec §7.3/§7.4, D12/D14): `AuthnGrpc` implements the generated
4	//! `AuthnService.Introspect`, and `AuthLayer` is the bearer-enforcement tower layer wrapping
5	//! the whole `grpc::router` (health + tenancy + authn) via `Server::builder().layer(..)`.
6	//!
7	//! Interceptors in tonic are sync-only, but `resolve` is async (a JWKS fetch may await), so
8	//! enforcement is a small tower `Service` rather than an interceptor. The layer wraps ALL
9	//! services on the server — including health — so the `:path` exemption check
10	//! (`/grpc.health.v1.Health/`, `/paigasus.iam.v1.AuthnService/Introspect`) runs BEFORE any
11	//! token extraction. A rejection renders a proper trailers-only gRPC response (HTTP 200,
12	//! `content-type: application/grpc`, `grpc-status` + ASCII-safe `grpc-message`) via
13	//! `tonic::Status::into_http` — never a bare HTTP 401, which a gRPC client can't interpret.
14	
15	use std::future::Future;
16	use std::pin::Pin;
17	use std::task::{Context, Poll};
18	
19	use paigasus_iam_core::{AuthnError, TokenDefect};
20	use paigasus_proto::paigasus::iam::v1::authn_service_server::AuthnService;
21	use paigasus_proto::paigasus::iam::v1::{IntrospectRequest, IntrospectResponse};
22	use tonic::body::Body;
23	use tonic::codegen::http;
24	use tonic::{Request, Response, Status};
25	use tower::{Layer, Service};
26	
27	use super::convert;
28	use crate::adapters::http::AppState;
29	use crate::adapters::http::auth_middleware::AuthContext;
30	use crate::application::authenticate_token::Provisioning;
31	
32	/// The `AuthnService` gRPC server — a thin adapter over the same `AppState.authn` use case
33	/// the HTTP `/v1/authn/introspect` handler drives.
34	pub struct AuthnGrpc {
35	    state: AppState,
36	}
37	
38	impl AuthnGrpc {
39	    pub fn new(state: AppState) -> Self {
40	        Self { state }
41	    }
42	}
43	
44	#[tonic::async_trait]
45	impl AuthnService for AuthnGrpc {
46	    /// `Introspect` (spec §7.2): the full `PrincipalContext` for a presented token. READ-ONLY
47	    /// (D10) — `AuthenticateToken::introspect` resolves with `Provisioning::Disabled`, so an
48	    /// unknown identity is `PermissionDenied` and this exempt RPC never has a user-creation
49	    /// side effect. The token IS the credential (in the request body, never the metadata):
50	    /// nothing here logs it, and errors funnel through `authn_status` (static messages only).
51	    async fn introspect(&self, request: Request<IntrospectRequest>) -> Result<Response<IntrospectResponse>, Status> {
52	        let token = request.into_inner().token;
53	        let ctx = self.state.authn.introspect(&token).await.map_err(|e| convert::authn_status(&e))?;
54	        Ok(Response::new(convert::to_introspect_response(&ctx)))
55	    }
56	}
57	
58	/// The bearer-enforcement tower `Layer`, applied to the whole gRPC server via
59	/// `Server::builder().layer(AuthLayer::new(state))` (D14 — wrapping the router is where the
60	/// integration tests exercise it). Clones cheaply (`AppState` is `Clone`).
61	#[derive(Clone)]
62	pub struct AuthLayer {
63	    state: AppState,
64	}
65	
66	impl AuthLayer {
67	    pub fn new(state: AppState) -> Self {
68	        Self { state }
69	    }
70	}
71	
72	impl<S> Layer<S> for AuthLayer {
73	    type Service = AuthEnforce<S>;
74	
75	    fn layer(&self, inner: S) -> Self::Service {
76	        AuthEnforce { inner, state: self.state.clone() }
77	    }
78	}
79	
80	/// The `Service` `AuthLayer` produces: on every request it runs the `:path` exemption check,
81	/// then (for a protected path) extracts the bearer, `resolve`s it with `Provisioning::Enabled`
82	/// (JIT-provisioning an unknown identity, mirroring the HTTP middleware), and either forwards
83	/// with an [`AuthContext`] extension attached or short-circuits with a trailers-only gRPC
84	/// error WITHOUT calling the inner service.
85	#[derive(Clone)]
86	pub struct AuthEnforce<S> {
87	    inner: S,
88	    state: AppState,
89	}
90	
91	/// Requests whose `:path` bypasses bearer enforcement (spec §7.4): the well-known health
92	/// service (all its methods, hence the prefix) and the unauthenticated `Introspect` RPC.
93	fn is_exempt(path: &str) -> bool {
94	    path.starts_with("/grpc.health.v1.Health/") || path == "/paigasus.iam.v1.AuthnService/Introspect"
95	}
96	
97	impl<S> Service<http::Request<Body>> for AuthEnforce<S>
98	where
99	    S: Service<http::Request<Body>, Response = http::Response<Body>> + Clone + Send + 'static,
100	    S::Future: Send + 'static,
101	{
102	    type Response = http::Response<Body>;
103	    type Error = S::Error;
104	    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send>>;
105	
106	    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
107	        self.inner.poll_ready(cx)
108	    }
109	
110	    fn call(&mut self, mut req: http::Request<Body>) -> Self::Future {
111	        // Swap the `poll_ready`-readied inner out and leave a clone behind, so the instance
112	        // moved into the boxed future is exactly the one that was readied (the canonical tower
113	        // middleware pattern). The clone will be readied on the next `poll_ready`.
114	        let clone = self.inner.clone();
115	        let mut inner = std::mem::replace(&mut self.inner, clone);
116	        let state = self.state.clone();
117	        Box::pin(async move {
118	            if is_exempt(req.uri().path()) {
119	                return inner.call(req).await;
120	            }
121	            // A missing or malformed `authorization` header is treated exactly like a rejected
122	            // token (D12): both are `Unauthenticated`.
123	            let Some(token) = bearer_token(req.headers()) else {
124	                return Ok(reject(&AuthnError::InvalidToken(TokenDefect::Malformed)));
125	            };
126	            match state.authn.resolve(&token, Provisioning::Enabled).await {
127	                Ok(principal) => {
128	                    req.extensions_mut().insert(AuthContext {
129	                        principal_id: principal.principal_id,
130	                        issuer: principal.issuer,
131	                        subject: principal.subject,
132	                    });
133	                    inner.call(req).await
134	                }
135	                Err(err) => Ok(reject(&err)),
136	            }
137	        })
138	    }
139	}
140	
141	/// Renders an `AuthnError` as a trailers-only gRPC error response (HTTP 200,
142	/// `content-type: application/grpc`, `grpc-status` + ASCII-safe `grpc-message`) via
143	/// `Status::into_http` — never a bare HTTP 401, which a gRPC client can't interpret.
144	fn reject(err: &AuthnError) -> http::Response<Body> {
145	    convert::authn_status(err).into_http()
146	}
147	
148	/// Extracts the bearer token from the `authorization` metadata (an HTTP header on the wrapped
149	/// gRPC request) — the sole accepted credential source, mirroring the HTTP middleware. Returns
150	/// `None` for an absent header, a non-ASCII value, a non-`Bearer` scheme, or an empty
151	/// credential. The scheme match is ASCII-case-insensitive per RFC 7235 §2.1.
152	fn bearer_token(headers: &http::HeaderMap) -> Option<String> {
153	    let value = headers.get(http::header::AUTHORIZATION)?.to_str().ok()?;
154	    let (scheme, token) = value.split_once(' ')?;
155	    if !scheme.eq_ignore_ascii_case("Bearer") {
156	        return None;
157	    }
158	    let token = token.trim();
159	    if token.is_empty() {
160	        return None;
161	    }
162	    Some(token.to_string())
163	}
