2	
3	//! The `Authenticator` v1 implementation (spec §4.1): a provider-agnostic OIDC access token
4	//! validator. Pipeline: length cap -> header decode + alg allowlist + `kid` presence ->
5	//! unverified `iss` read -> exact issuer match -> JWKS `kid` lookup -> JWK/alg family
6	//! consistency -> signature + claims validation (issuer/audience/expiry) -> `ValidatedClaims`.
7	//! Never logs token or claim material (`TokenDefect` itself carries no payload).
8	
9	use async_trait::async_trait;
10	use base64::Engine;
11	use base64::engine::general_purpose::URL_SAFE_NO_PAD;
12	use chrono::{DateTime, Utc};
13	use jsonwebtoken::errors::ErrorKind;
14	use jsonwebtoken::jwk::{AlgorithmParameters, Jwk};
15	use jsonwebtoken::{Algorithm, DecodingKey, Validation, decode, decode_header};
16	use paigasus_iam_core::{Authenticator, AuthnError, Clock, Issuer, TokenDefect, ValidatedClaims};
17	use serde::Deserialize;
18	
19	use crate::adapters::oidc::jwks::{JwksCache, JwksFetcher, JwksProvider};
20	use crate::config::IssuerConfig;
21	
22	/// Algorithms this validator accepts (spec §4.1) — RSA/EC signature algorithms only.
23	/// Deliberately excludes HMAC (a shared-secret alg would let anyone holding a *public*
24	/// verification artifact sign forged tokens) and `none` (which `jsonwebtoken` doesn't even
25	/// model as an `Algorithm` variant).
26	const ALLOWED_ALGORITHMS: [Algorithm; 2] = [Algorithm::RS256, Algorithm::ES256];
27	
28	/// The `Authenticator` v1 implementation: validates a presented bearer token against a
29	/// fixed, operator-configured set of OIDC issuers (spec §4.1). Generic-by-value over its
30	/// `JwksProvider`'s three collaborators (fetcher/cache/clock), mirroring the provider's own
31	/// composition convention — the concrete adapters are chosen once at the composition root
32	/// (Task 14), not boxed as trait objects here.
33	pub struct OidcAuthenticator<F: JwksFetcher, K: JwksCache, C: Clock> {
34	    issuers: Vec<IssuerConfig>,
35	    provider: JwksProvider<F, K, C>,
36	    leeway_secs: u64,
37	    max_token_bytes: usize,
38	}
39	
40	impl<F: JwksFetcher, K: JwksCache, C: Clock> OidcAuthenticator<F, K, C> {
41	    pub fn new(issuers: Vec<IssuerConfig>, provider: JwksProvider<F, K, C>, leeway_secs: u64, max_token_bytes: usize) -> Self {
42	        Self {
43	            issuers,
44	            provider,
45	            leeway_secs,
46	            max_token_bytes,
47	        }
48	    }
49	
50	    /// Exact string match against the configured issuer list (spec §3.1's "no
51	    /// normalization" rule applies here too — this is compared byte-for-byte, same as
52	    /// `Issuer::parse`'s own equality semantics).
53	    fn find_issuer_config(&self, iss: &str) -> Option<&IssuerConfig> {
54	        self.issuers.iter().find(|cfg| cfg.issuer == iss)
55	    }
56	}
57	
58	fn invalid(defect: TokenDefect) -> AuthnError {
59	    AuthnError::InvalidToken(defect)
60	}
61	
62	/// The `iss` claim, read WITHOUT verifying the token's signature — used only to pick which
63	/// issuer's JWKS to check against (spec §4.1). Nothing else is ever read from this
64	/// unverified payload, and the payload/token is never logged (it's attacker-controlled
65	/// prior to signature verification).
66	#[derive(Deserialize)]
67	struct UnverifiedIss {
68	    iss: String,
69	}
70	
71	fn read_unverified_issuer(token: &str) -> Result<String, AuthnError> {
72	    let mut parts = token.split('.');
73	    let (Some(_header), Some(payload)) = (parts.next(), parts.next()) else {
74	        return Err(invalid(TokenDefect::Malformed));
75	    };
76	    let decoded = URL_SAFE_NO_PAD.decode(payload).map_err(|_| invalid(TokenDefect::Malformed))?;
77	    let unverified: UnverifiedIss = serde_json::from_slice(&decoded).map_err(|_| invalid(TokenDefect::Malformed))?;
78	    Ok(unverified.iss)
79	}
80	
81	/// `aud` per RFC 7519 §4.1.3 may be encoded as a single string or an array of strings.
82	#[derive(Deserialize)]
83	#[serde(untagged)]
84	enum WireAudience {
85	    Single(String),
86	    Multiple(Vec<String>),
87	}
88	
89	impl WireAudience {
90	    fn into_vec(self) -> Vec<String> {
91	        match self {
92	            WireAudience::Single(aud) => vec![aud],
93	            WireAudience::Multiple(auds) => auds,
94	        }
95	    }
96	}
97	
98	/// The claims this validator reads off a token, deserialized only AFTER `jsonwebtoken` has
99	/// verified the signature (spec §4.1). `sub`/`exp`/`aud` are required — their absence (or a
100	/// wrong-shaped value) is a serde failure, which `map_jwt_error` collapses to `Malformed`;
101	/// the profile claims are optional since an IdP may omit any of them.
102	#[derive(Deserialize)]
103	struct WireClaims {
104	    sub: String,
105	    exp: u64,
106	    aud: WireAudience,
107	    email: Option<String>,
108	    name: Option<String>,
109	    locale: Option<String>,
110	    zoneinfo: Option<String>,
111	}
112	
113	/// Maps a `jsonwebtoken` decode/validation failure to a `TokenDefect` (spec §4.1). Every
114	/// kind this validator doesn't specifically distinguish (bad base64, malformed JSON, a
115	/// wrong-shaped claim, an unhandled `ErrorKind`) collapses to `Malformed`.
116	fn map_jwt_error(err: jsonwebtoken::errors::Error) -> AuthnError {
117	    match err.into_kind() {
118	        ErrorKind::ExpiredSignature => invalid(TokenDefect::Expired),
119	        ErrorKind::ImmatureSignature => invalid(TokenDefect::NotYetValid),
120	        ErrorKind::InvalidSignature => invalid(TokenDefect::BadSignature),
121	        ErrorKind::InvalidAudience => invalid(TokenDefect::AudienceMismatch),
122	        ErrorKind::InvalidIssuer => invalid(TokenDefect::IssuerNotConfigured),
123	        _ => invalid(TokenDefect::Malformed),
124	    }
125	}
126	
127	/// The JWK's key type must match the family the header's algorithm belongs to (an RSA key
128	/// can't produce an ES256 signature, and vice versa). A mismatch here means this JWKS entry
129	/// could never have produced the token's signature — the same "this alg isn't usable" shape
130	/// as an unsupported algorithm, hence the shared `UnsupportedAlg` defect (spec §4.1 D-note).
131	fn check_kty_matches_alg(jwk: &Jwk, alg: Algorithm) -> Result<(), AuthnError> {
132	    let consistent = matches!(
133	        (&jwk.algorithm, alg),
134	        (AlgorithmParameters::RSA(_), Algorithm::RS256) | (AlgorithmParameters::EllipticCurve(_), Algorithm::ES256)
135	    );
136	    if consistent { Ok(()) } else { Err(invalid(TokenDefect::UnsupportedAlg)) }
137	}
138	
139	#[async_trait]
140	impl<F: JwksFetcher, K: JwksCache, C: Clock> Authenticator for OidcAuthenticator<F, K, C> {
141	    async fn authenticate(&self, token: &str) -> Result<ValidatedClaims, AuthnError> {
142	        // 1. Length cap — before any parsing at all.
143	        if token.len() > self.max_token_bytes {
144	            return Err(invalid(TokenDefect::Oversized));
145	        }
146	
147	        // 2. Header decode + alg allowlist + kid presence — header-only checks, no I/O and
148	        // no unverified-payload reads yet.
149	        let header = decode_header(token).map_err(|_| invalid(TokenDefect::Malformed))?;
150	        if !ALLOWED_ALGORITHMS.contains(&header.alg) {
151	            return Err(invalid(TokenDefect::UnsupportedAlg));
152	        }
153	        let kid = header.kid.ok_or_else(|| invalid(TokenDefect::UnknownKid))?;
154	
155	        // 3. Unverified `iss` read, then exact match against configured issuers.
156	        let unverified_iss = read_unverified_issuer(token)?;
157	        let issuer_config = self.find_issuer_config(&unverified_iss).ok_or_else(|| invalid(TokenDefect::IssuerNotConfigured))?;
158	        let issuer = Issuer::parse(&issuer_config.issuer).map_err(|_| invalid(TokenDefect::IssuerNotConfigured))?;
159	
160	        // 4. JWKS lookup + kty/alg consistency.
161	        let jwk = self.provider.key_for(&issuer, &kid).await?;
162	        check_kty_matches_alg(&jwk, header.alg)?;
163	        let decoding_key = DecodingKey::from_jwk(&jwk).map_err(|_| invalid(TokenDefect::BadSignature))?;
164	
165	        // 5. Signature + claims validation, pinned to exactly the header's algorithm.
166	        let mut validation = Validation::new(header.alg);
167	        validation.set_issuer(&[issuer.as_str()]);
168	        validation.set_audience(&issuer_config.audiences);
169	        validation.leeway = self.leeway_secs;
170	        validation.validate_nbf = true;
171	
172	        let token_data = decode::<WireClaims>(token, &decoding_key, &validation).map_err(map_jwt_error)?;
173	
174	        let expires_at = i64::try_from(token_data.claims.exp)
175	            .ok()
176	            .and_then(|secs| DateTime::<Utc>::from_timestamp(secs, 0))
177	            .ok_or_else(|| invalid(TokenDefect::Malformed))?;
178	
179	        Ok(ValidatedClaims {
180	            issuer,
181	            subject: token_data.claims.sub,
182	            audiences: token_data.claims.aud.into_vec(),
183	            expires_at,
184	            email: token_data.claims.email,
185	            name: token_data.claims.name,
186	            locale: token_data.claims.locale,
187	            zoneinfo: token_data.claims.zoneinfo,
188	        })
189	    }
190	}
