209	    /// Keycloak integration test instead). Returns the signing key, the corresponding
210	    /// public JWK, and a fixed `kid` tying the two together.
211	    fn es256_keypair() -> (EncodingKey, Jwk, String) {
212	        let secret_key = p256::SecretKey::random(&mut OsRng);
213	        let pem = secret_key.to_pkcs8_pem(LineEnding::LF).expect("valid pkcs8 pem");
214	        let encoding_key = EncodingKey::from_ec_pem(pem.as_bytes()).expect("valid ec pem");
215	
216	        let encoded_point = secret_key.public_key().to_encoded_point(false);
217	        let x = URL_SAFE_NO_PAD.encode(encoded_point.x().expect("uncompressed point has x"));
218	        let y = URL_SAFE_NO_PAD.encode(encoded_point.y().expect("uncompressed point has y"));
219	
220	        let kid = "test-es256-key".to_string();
221	        let jwk = Jwk {
222	            common: CommonParameters {
223	                key_algorithm: Some(KeyAlgorithm::ES256),
224	                key_id: Some(kid.clone()),
225	                ..Default::default()
226	            },
227	            algorithm: AlgorithmParameters::EllipticCurve(EllipticCurveKeyParameters {
228	                key_type: EllipticCurveKeyType::EC,
229	                curve: EllipticCurve::P256,
230	                x,
231	                y,
232	            }),
233	        };
234	
235	        (encoding_key, jwk, kid)
236	    }
