3	//! Authn HTTP surface: `POST /v1/authn/introspect` plus the dedicated `AuthnError` →
4	//! response funnel (spec §6.3, D12). This funnel is deliberately SEPARATE from the tenancy
5	//! `ApiError`/`ErrorClass` machinery — that path can only express 400/404/409/500, while
6	//! authn needs 401 (+ `WWW-Authenticate`), 403 subcodes, and 503. Bodies reuse the same
7	//! `{"error":{code,message}}` envelope; every message is STATIC per code — no claim
8	//! values, token fragments, or upstream error text ever reach the response (spec §6.3).
9	
10	use axum::http::{HeaderValue, StatusCode, header};
11	use axum::response::{IntoResponse, Response};
12	use axum::routing::post;
13	use axum::{Json, Router, extract::State};
14	use paigasus_iam_core::AuthnError;
15	use serde_json::json;
16	
17	use super::AppState;
18	use super::dto::{IntrospectBody, IntrospectResponseDto};
19	
20	/// The `WWW-Authenticate` challenge attached to every 401 (RFC 6750 §3).
21	const BEARER_CHALLENGE: &str = "Bearer error=\"invalid_token\"";
22	
23	/// Wraps an `AuthnError` so handlers can return it via `?` (see `From` below) and axum
24	/// renders the spec §6.3 mapping. Task 11's middleware reuses this for its own rejects.
25	pub struct AuthnApiError(pub AuthnError);
26	
27	impl From<AuthnError> for AuthnApiError {
28	    fn from(err: AuthnError) -> Self {
29	        AuthnApiError(err)
30	    }
31	}
32	
33	impl IntoResponse for AuthnApiError {
34	    fn into_response(self) -> Response {
35	        let (status, code, message) = match &self.0 {
36	            AuthnError::InvalidToken(_) => (StatusCode::UNAUTHORIZED, "invalid_token", "invalid bearer token"),
37	            AuthnError::IdentityNotProvisioned => (StatusCode::FORBIDDEN, "identity_not_provisioned", "identity not provisioned"),
38	            AuthnError::ProvisioningFailed(_) => (StatusCode::FORBIDDEN, "provisioning_failed", "provisioning failed"),
39	            AuthnError::PrincipalInactive => (StatusCode::FORBIDDEN, "principal_inactive", "principal inactive"),
40	            AuthnError::Unavailable => (StatusCode::SERVICE_UNAVAILABLE, "unavailable", "authentication backend unavailable"),
41	            AuthnError::Backend(_) => {
42	                // Debug carries the boxed repository/infra source (never token or claim
43	                // material by `AuthnError`'s own contract) — logged here, never surfaced.
44	                tracing::error!(error = ?self.0, "internal error handling an authn request");
45	                (StatusCode::INTERNAL_SERVER_ERROR, "internal", "internal error")
46	            }
47	        };
48	
49	        let mut response = (status, Json(json!({ "error": { "code": code, "message": message } }))).into_response();
50	        if matches!(self.0, AuthnError::InvalidToken(_)) {
51	            response.headers_mut().insert(header::WWW_AUTHENTICATE, HeaderValue::from_static(BEARER_CHALLENGE));
52	        }
53	        response
54	    }
55	}
56	
57	/// The introspect sub-router. Merged alongside (NOT inside) the tenancy `/v1` sub-router
58	/// in `super::router` so Task 11's bearer-enforcement layer, which wraps the tenancy
59	/// sub-router only, never covers this route (middleware-exempt, spec §7.4).
60	pub fn router() -> Router<AppState> {
61	    Router::new().route("/v1/authn/introspect", post(introspect))
62	}
63	
64	/// `POST /v1/authn/introspect` (spec §7.2): the full `PrincipalContext` for a presented
65	/// token. READ-ONLY (D10): `AuthenticateToken::introspect` resolves with
66	/// `Provisioning::Disabled`, so an unknown identity is 403 `identity_not_provisioned` and
67	/// this unauthenticated endpoint never has a user-creation side effect. The body carries
68	/// the credential itself and is NEVER logged (nothing here logs, and an oversized token is
69	/// rejected by the validator's own length cap — no pre-filtering, no echo).
70	async fn introspect(State(state): State<AppState>, Json(body): Json<IntrospectBody>) -> Result<Json<IntrospectResponseDto>, AuthnApiError> {
71	    let ctx = state.authn.introspect(&body.token).await?;
72	    Ok(Json(ctx.into()))
73	}
