82	    async fn rendered(err: AuthnError) -> (StatusCode, Option<String>, serde_json::Value) {
83	        let response = AuthnApiError(err).into_response();
84	        let status = response.status();
85	        let challenge = response.headers().get(header::WWW_AUTHENTICATE).map(|v| v.to_str().unwrap().to_string());
86	        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
87	        (status, challenge, serde_json::from_slice(&bytes).unwrap())
88	    }
