131	    /// Boot-time validation beyond what serde/figment structurally enforce (spec §6.4):
132	    /// at least one issuer, issuers unique (compared on the TRIMMED string, so a padded
133	    /// duplicate is still caught), each issuer string carries no leading/trailing
134	    /// whitespace of its own (padding is never valid config, even when unique), each
135	    /// issuer's `audiences` non-empty, each issuer string a valid absolute `https` URL
136	    /// (`Issuer::parse`), and a `redis` JWKS cache backend has `redis_url` configured.
137	    pub fn validate(&self) -> Result<(), String> {
138	        if self.authn.issuers.is_empty() {
139	            return Err("authn.issuers must contain at least one issuer".to_string());
140	        }
141	
142	        let mut seen = HashSet::with_capacity(self.authn.issuers.len());
143	        for issuer_cfg in &self.authn.issuers {
144	            let raw = issuer_cfg.issuer.as_str();
145	            let trimmed = raw.trim();
146	            if !seen.insert(trimmed) {
147	                return Err(format!("authn.issuers contains a duplicate issuer (after trimming whitespace): {trimmed}"));
148	            }
149	            if raw != trimmed {
150	                return Err(format!("authn.issuers[{trimmed}] has leading/trailing whitespace, which is never valid config: {raw:?}"));
151	            }
152	            if issuer_cfg.audiences.is_empty() {
153	                return Err(format!("authn.issuers[{trimmed}].audiences must not be empty"));
154	            }
155	            if let Err(e) = Issuer::parse(&issuer_cfg.issuer) {
156	                return Err(format!("authn.issuers[{trimmed}] is not a valid issuer: {e}"));
157	            }
158	        }
159	
160	        if self.authn.jwks_cache.backend == JwksCacheBackend::Redis && self.authn.jwks_cache.redis_url.is_none() {
161	            return Err("authn.jwks_cache.backend = \"redis\" requires authn.jwks_cache.redis_url".to_string());
162	        }
163	
164	        Ok(())
165	    }
166	}
