141	    /// Full authorization context for a request (§6.1): `resolve(.., Disabled)` (D10, never
142	    /// provisions) plus every membership row, paged internally (D13 — this is the only
143	    /// entry point that fetches memberships).
144	    pub async fn introspect(&self, token: &str) -> Result<PrincipalContext, AuthnError> {
145	        let principal = self.resolve(token, Provisioning::Disabled).await?;
146	
147	        let mut memberships = Vec::new();
148	        let mut offset = 0u64;
149	        loop {
150	            let page = self.memberships.list_by_principal(principal.principal_id.uuid(), MEMBERSHIP_PAGE_SIZE, offset).await.map_err(backend)?;
151	            let page_len = page.len() as u64;
152	            memberships.extend(page);
153	            if page_len < MEMBERSHIP_PAGE_SIZE {
154	                break;
155	            }
156	            offset += MEMBERSHIP_PAGE_SIZE;
157	        }
158	
159	        Ok(PrincipalContext {
160	            principal,
161	            memberships,
162	            role_groups: Vec::new(),
163	        })
