166	    /// Just-in-time provisioning (§6.2). `email` is required (absent, or unparseable ->
167	    /// `ProvisioningFailed(MissingEmail)`); `display_name` is the `name` claim, falling back
168	    /// to the email's local part; `locale`/`zoneinfo` pass through untouched. One call to
169	    /// `ExternalIdentityRepository::provision` spans principal + user + external_identity in
170	    /// a single transaction (D9). A lost race (`Conflict(ExternalIdentityExists)`) re-reads
171	    /// the winner's row and proceeds with it — no orphan principal/user, no auto-linking by
172	    /// email (D5): an email conflict fails provisioning instead.
173	    async fn jit_provision(&self, claims: &ValidatedClaims) -> Result<PrincipalId, AuthnError> {
174	        let email = match claims.email.as_deref().map(Email::parse) {
175	            Some(Ok(email)) => email,
176	            _ => return Err(AuthnError::ProvisioningFailed(ProvisioningDefect::MissingEmail)),
177	        };
178	        let local_part = email.as_str().split('@').next().unwrap_or_default().to_string();
179	        let display_name = claims.name.clone().unwrap_or(local_part);
180	
181	        let now = self.clock.now();
182	        let principal_id = self.id_gen.new_principal_id();
183	        let principal = Principal::new(principal_id.clone(), PrincipalKind::User, PrincipalStatus::Active, now, now);
184	        let user = User::new(principal_id.clone(), email, display_name, claims.locale.clone(), claims.zoneinfo.clone(), now, now);
185	        let identity = ExternalIdentity {
186	            id: self.id_gen.new_external_identity_id(),
187	            principal_id: principal_id.clone(),
188	            issuer: claims.issuer.clone(),
189	            subject: claims.subject.clone(),
190	            created_at: now,
191	            updated_at: now,
192	        };
193	
194	        match self.identities.provision(&principal, &user, &identity).await {
195	            Ok(()) => Ok(principal_id),
196	            Err(RepositoryError::Conflict(ConflictKind::ExternalIdentityExists)) => self
197	                .identities
198	                .find_by_issuer_subject(&claims.issuer, &claims.subject)
199	                .await
200	                .map_err(backend)?
