3	//! Redis-backed `JwksCache` (spec §4.3/D15): an external, shared cache so `CachedJwks`
4	//! survives process restarts and is visible across replicas. Redis owns the TTL directly
5	//! (`SET ... EX ttl_secs`) rather than this adapter tracking freshness itself — an expired
6	//! key simply disappears server-side. Every Redis failure (connect, I/O, or (de)serialize)
7	//! maps to `AuthnError::Unavailable`: a cache outage fails closed, distinguishable from a
8	//! token-validity error, but never surfaces cached values or connection details in logs —
9	//! only the issuer and the `redis::ErrorKind`/a static tag are logged.
10	
11	use async_trait::async_trait;
12	use paigasus_iam_core::{AuthnError, Issuer};
13	use redis::aio::ConnectionManager;
14	use redis::{AsyncCommands, Client};
15	
16	use super::jwks::{CachedJwks, JwksCache};
17	
18	/// Redis key prefix for cached JWKS entries (spec §4.3): `iam:jwks:<issuer canonical
19	/// string>`.
20	const KEY_PREFIX: &str = "iam:jwks:";
21	
22	fn cache_key(issuer: &Issuer) -> String {
23	    format!("{KEY_PREFIX}{}", issuer.as_str())
24	}
25	
26	/// `JwksCache` backed by Redis via an auto-reconnecting `ConnectionManager` (spec §4.3/D15).
27	/// `ConnectionManager` is cheap to clone (an `Arc`-wrapped multiplexed connection designed
28	/// for concurrent callers), so `get`/`put` clone it per call rather than holding a lock.
29	/// `connect` is the sole constructor — Task 10's composition root calls it verbatim.
30	pub struct RedisJwksCache {
31	    conn: ConnectionManager,
32	    ttl_secs: u64,
33	}
34	
35	impl RedisJwksCache {
36	    /// Opens `redis_url` and wraps it in a `ConnectionManager`, which transparently
37	    /// reconnects in the background on transient connection loss (the in-flight command
38	    /// that observed the drop still surfaces its error to the caller — see `get`/`put`
39	    /// below). `ttl_secs` is applied to every `put` as Redis's own `EX` expiry.
40	    pub async fn connect(redis_url: &str, ttl_secs: u64) -> Result<Self, AuthnError> {
41	        let client = Client::open(redis_url).map_err(|err| log_unavailable(None, err.kind()))?;
42	        let conn = ConnectionManager::new(client).await.map_err(|err| log_unavailable(None, err.kind()))?;
43	        Ok(Self { conn, ttl_secs })
44	    }
45	}
46	
47	#[async_trait]
48	impl JwksCache for RedisJwksCache {
49	    async fn get(&self, issuer: &Issuer) -> Result<Option<CachedJwks>, AuthnError> {
50	        let key = cache_key(issuer);
51	        let mut conn = self.conn.clone();
52	        let raw: Option<Vec<u8>> = conn.get(&key).await.map_err(|err| log_unavailable(Some(issuer), err.kind()))?;
53	        match raw {
54	            None => Ok(None),
55	            Some(bytes) => serde_json::from_slice(&bytes).map(Some).map_err(|_| log_serde_unavailable(issuer)),
56	        }
57	    }
58	
59	    async fn put(&self, issuer: &Issuer, jwks: CachedJwks) -> Result<(), AuthnError> {
60	        let key = cache_key(issuer);
61	        let payload = serde_json::to_vec(&jwks).map_err(|_| log_serde_unavailable(issuer))?;
62	        let mut conn = self.conn.clone();
63	        let _: () = conn.set_ex(&key, payload, self.ttl_secs).await.map_err(|err| log_unavailable(Some(issuer), err.kind()))?;
64	        Ok(())
65	    }
66	}
67	
68	/// Logs the issuer (when available) and the Redis error's `ErrorKind` only — never the
69	/// error's `Display`/message, which can echo connection details — then maps to
70	/// `Unavailable` (spec §4.3/D15: fail closed, but distinguishable from token invalidity).
71	fn log_unavailable(issuer: Option<&Issuer>, kind: redis::ErrorKind) -> AuthnError {
72	    match issuer {
73	        Some(issuer) => tracing::warn!(issuer = %issuer, error_kind = ?kind, "redis jwks cache error"),
74	        None => tracing::warn!(error_kind = ?kind, "redis jwks cache connect error"),
75	    }
76	    AuthnError::Unavailable
77	}
78	
79	/// Same fail-closed mapping as `log_unavailable`, for the `serde_json` (de)serialize path,
80	/// which has no `redis::ErrorKind` of its own.
81	fn log_serde_unavailable(issuer: &Issuer) -> AuthnError {
82	    tracing::warn!(issuer = %issuer, error_kind = "serde_json", "redis jwks cache error");
83	    AuthnError::Unavailable
84	}
