169	/// Full HTTP surface: liveness + DB-backed readiness + the `/v1` tenancy API + authn
170	/// introspection. The tenancy routes (organizations/teams/projects/memberships/users) sit
171	/// on their own sub-router carrying the bearer-enforcement `route_layer` (D14 — attached
172	/// HERE, inside `router()`, not in `serve_http`, so the `oneshot` test harness exercises
173	/// it). `/healthz`, `/readyz`, and `POST /v1/authn/introspect` are merged OUTSIDE that
174	/// layer and stay unauthenticated (spec §7.4).
175	pub fn router(state: AppState) -> Router {
176	    let protected = Router::new()
177	        .merge(organizations::router())
178	        .merge(teams::router())
179	        .merge(projects::router())
180	        .merge(memberships::router())
181	        .merge(users::router())
182	        // `route_layer` (not `layer`): the enforcement covers exactly the routes defined
183	        // above and never the merged-in `/healthz`/`/readyz`/introspect or the 404 fallback.
184	        .route_layer(axum::middleware::from_fn_with_state(state.clone(), auth_middleware::require_bearer))
185	        .with_state(state.clone());
186	    let public = Router::new().route("/readyz", get(readyz)).with_state(state.clone());
187	    let authn_api = authn::router().with_state(state);
188	    health_router().merge(protected).merge(public).merge(authn_api)
189	}
