195	async fn readyz(State(state): State<AppState>) -> impl IntoResponse {
196	    let ping = state.db.execute(Statement::from_string(state.db.get_database_backend(), "SELECT 1")).await;
197	    match ping {
198	        Ok(_) => (StatusCode::OK, Json(json!({ "status": "ready" }))),
199	        Err(e) => {
200	            tracing::warn!(error = %e, "readiness check failed: database ping error");
201	            (StatusCode::SERVICE_UNAVAILABLE, Json(json!({ "status": "unready" })))
202	        }
203	    }
204	}
