206	/// Serve the HTTP surface on `addr` until `shutdown` resolves.
207	pub async fn serve_http(addr: SocketAddr, state: AppState, request_timeout: Duration, shutdown: impl std::future::Future<Output = ()> + Send + 'static) -> std::io::Result<()> {
208	    // `TimeoutLayer::new` is deprecated since tower-http 0.6.7 in favor of
209	    // `with_status_code`; `REQUEST_TIMEOUT` (408) reproduces `new`'s prior default.
210	    let app = router(state)
211	        .layer(TraceLayer::new_for_http())
212	        .layer(TimeoutLayer::with_status_code(StatusCode::REQUEST_TIMEOUT, request_timeout));
213	    let listener = tokio::net::TcpListener::bind(addr).await?;
214	    axum::serve(listener, app).with_graceful_shutdown(shutdown).await
215	}
