74	/// An in-process mock OIDC IdP: an HTTPS axum server (self-signed runtime cert) serving
75	/// the discovery document + JWKS, plus the ES256 signing key to mint bearer tokens whose
76	/// signatures verify against that JWKS. The served JWKS lives behind an `Arc<RwLock<..>>`
77	/// shared with the server task so [`MockIdp::rotate`] can swap the keypair at runtime
78	/// (the key-rotation integration test, spec §8). The server task is aborted on drop.
79	#[allow(dead_code)]
80	pub struct MockIdp {
81	    pub issuer: String,
82	    sign: EncodingKey,
83	    kid: String,
84	    /// The serialized JWKS the `/jwks` route serves; `rotate` replaces it in place, and the
85	    /// server reads it (under the same lock) on every request.
86	    jwks_body: Arc<RwLock<String>>,
87	    handle: JoinHandle<()>,
88	}
89	
90	#[allow(dead_code)]
91	impl MockIdp {
92	    /// Mints a signed ES256 bearer token: `iss` = this IdP, plus the given `sub`/`aud`,
93	    /// `exp` = now + `exp_offset_secs` (negative for an already-expired token), and an
94	    /// optional `email` claim (JIT provisioning requires one, spec §6.2). Signs with the
95	    /// CURRENT keypair, so a token minted after [`rotate`](Self::rotate) carries the new `kid`.
96	    pub fn bearer(&self, sub: &str, email: Option<&str>, aud: &str, exp_offset_secs: i64) -> String {
97	        let mut header = Header::new(Algorithm::ES256);
98	        header.kid = Some(self.kid.clone());
99	        let mut claims = serde_json::json!({
100	            "iss": self.issuer,
101	            "sub": sub,
102	            "aud": aud,
103	            "exp": chrono::Utc::now().timestamp() + exp_offset_secs,
104	        });
105	        if let Some(email) = email {
106	            claims["email"] = Value::String(email.to_string());
107	        }
108	        jsonwebtoken::encode(&header, &claims, &self.sign).expect("signing a test token")
109	    }
110	
111	    /// Rotates the IdP's signing key: mints a fresh ES256 keypair under a NEW `kid`, swaps
112	    /// it into the served JWKS, and switches `bearer` to sign with it. A token minted after
113	    /// this carries the new `kid`, so the validator's cached JWKS (keyed by the old `kid`)
114	    /// misses and must refetch (§4.3) — the key-rotation integration test. The timestamp
115	    /// suffix guarantees the new `kid` differs from the old one across repeated rotations.
116	    pub fn rotate(&mut self) {
117	        let kid = format!("mock-idp-es256-{}", chrono::Utc::now().timestamp_nanos_opt().unwrap_or_default());
118	        let (sign, jwk) = es256_keypair(&kid);
119	        let body = serde_json::to_string(&JwkSet { keys: vec![jwk] }).expect("jwks serializes");
120	        *self.jwks_body.write().expect("jwks lock not poisoned") = body;
121	        self.sign = sign;
122	        self.kid = kid;
123	    }
124	}
