132	/// Mints a runtime EC P-256 keypair under the given `kid` (test-support copy of the
133	/// validator's inline helper — spec §8 mock-IdP refinement: no committed PEM/JWK fixtures,
134	/// no `rsa` crate). Returns the signing key and the corresponding public JWK, both tagged
135	/// with `kid`. The caller owns `kid` so `rotate` can mint a distinct one per rotation.
136	fn es256_keypair(kid: &str) -> (EncodingKey, Jwk) {
137	    let secret_key = p256::SecretKey::random(&mut OsRng);
138	    let pem = secret_key.to_pkcs8_pem(LineEnding::LF).expect("valid pkcs8 pem");
139	    let encoding_key = EncodingKey::from_ec_pem(pem.as_bytes()).expect("valid ec pem");
140	
141	    let encoded_point = secret_key.public_key().to_encoded_point(false);
142	    let x = URL_SAFE_NO_PAD.encode(encoded_point.x().expect("uncompressed point has x"));
143	    let y = URL_SAFE_NO_PAD.encode(encoded_point.y().expect("uncompressed point has y"));
144	
145	    let jwk = Jwk {
146	        common: CommonParameters {
147	            key_algorithm: Some(KeyAlgorithm::ES256),
148	            key_id: Some(kid.to_string()),
149	            ..Default::default()
150	        },
151	        algorithm: AlgorithmParameters::EllipticCurve(EllipticCurveKeyParameters {
152	            key_type: EllipticCurveKeyType::EC,
153	            curve: EllipticCurve::P256,
154	            x,
155	            y,
156	        }),
157	    };
158	
159	    (encoding_key, jwk)
160	}
