294	/// Attaches an `authorization: Bearer <token>` metadata entry to a gRPC request — the gRPC
295	/// surface's bearer credential (Task 12 enforcement), mirroring the HTTP `Authorization`
296	/// header the axum middleware reads. Protected `TenancyService` calls carry it; the exempt
297	/// routes (`Introspect`, health) are called without it.
298	#[allow(dead_code)]
299	pub fn grpc_bearer<T>(req: &mut tonic::Request<T>, token: &str) {
300	    let value: tonic::metadata::MetadataValue<tonic::metadata::Ascii> = format!("Bearer {token}").parse().expect("bearer token is valid ascii metadata");
301	    req.metadata_mut().insert("authorization", value);
302	}
