238	    // 1. A token under the ORIGINAL key validates (and warms the per-issuer JWKS cache).
239	    let before = idp.bearer("rotating-user", Some("rotate@example.com"), "paigasus", 3600);
240	    let (status, body) = send(&app, "POST", "/v1/organizations", Some(json!({ "slug": "pre", "name": "Pre" })), Some(&before)).await;
241	    assert_eq!(status, StatusCode::CREATED, "{body}");
242	
243	    // 2. Rotate the IdP's signing key: the served JWKS now carries only the NEW kid, while
244	    // the validator's cache still holds the old one.
