248	    // IdP serves the rotated JWKS, the signature verifies against the fresh key, and the
249	    // protected write succeeds.
250	    let after = idp.bearer("rotating-user", Some("rotate@example.com"), "paigasus", 3600);
251	    let (status, body) = send(&app, "POST", "/v1/organizations", Some(json!({ "slug": "post", "name": "Post" })), Some(&after)).await;
