280	        ("PATCH", format!("/v1/teams/{id}")),
281	        ("POST", format!("/v1/teams/{id}/archive")),
282	        ("POST", format!("/v1/teams/{id}/restore")),
283	        ("POST", format!("/v1/teams/{id}/projects")),
284	        ("GET", format!("/v1/teams/{id}/projects")),
285	        // projects.rs
286	        ("GET", format!("/v1/projects/{id}")),
